# Generated by GitHub Copilot
@router.delete(
    "/releases/{release_id}/prs/cleanup-nullrepo",
    summary="Remove duplicate PR rows that have no repository set",
)
def cleanup_null_repo_prs(release_id: int, db: Session = Depends(get_db)) -> dict:
    """Delete pull_request rows for a release where ``repository IS NULL``.

    These are orphaned duplicates created when PRs were first synced before
    the repository field was resolved, and later re-synced with the correct
    repository name, leaving two rows per PR number.
    """
    from models import PullRequest
    rows = (
        db.query(PullRequest)
        .filter(
            PullRequest.release_id == release_id,
            PullRequest.repository.is_(None),
        )
        .all()
    )
    count = len(rows)
    for row in rows:
        db.delete(row)
    db.commit()
    return {"release_id": release_id, "deleted": count}


