# Generated by GitHub Copilot
@router.post(
    "/prs/remap-by-milestone-version",
    summary="Remap each PR to the release whose version matches its milestone_version",
)
def remap_prs_by_milestone_version(db: Session = Depends(get_db)) -> dict:
    """For every pull_request row that has a ``milestone_version`` set, look up
    the release whose ``version`` column matches (case-insensitive, optional
    leading 'v' stripped) and update ``release_id`` accordingly.

    PRs whose ``milestone_version`` does not match any release are left
    unchanged so no data is lost.

    Returns a per-version breakdown of how many rows were reassigned.
    """
    from models import PullRequest

    releases = db.query(Release).all()

    # Build normalised version → release mapping
    version_to_release: dict[str, Release] = {}
    for rel in releases:
        if rel.version and rel.version.upper() != "UNVERSIONED":
            key = rel.version.lstrip("vV").lower()
            version_to_release[key] = rel

    prs = db.query(PullRequest).filter(PullRequest.milestone_version.isnot(None)).all()

    summary: dict[str, dict] = {}

    for pr in prs:
        ms_ver = (pr.milestone_version or "").lstrip("vV").lower()
        target_release = version_to_release.get(ms_ver)
        if not target_release:
            continue

        ver_label = pr.milestone_version
        if ver_label not in summary:
            summary[ver_label] = {
                "version": ver_label,
                "release_id": target_release.release_id,
                "release_name": target_release.release_name,
                "prs_remapped": 0,
            }

        if pr.release_id != target_release.release_id:
            pr.release_id = target_release.release_id
            summary[ver_label]["prs_remapped"] += 1

    db.commit()

    return {
        "total_remapped": sum(v["prs_remapped"] for v in summary.values()),
        "breakdown": list(summary.values()),
    }


# Generated by GitHub Copilot
@router.post(
    "/releases/{release_id}/prs/backfill-version",
    summary="Backfill milestone_version for existing PRs from release version",
)
def backfill_pr_versions(release_id: int, db: Session = Depends(get_db)) -> dict:
    """Populate ``milestone_version`` on every pull request row that belongs to
    this release but currently has a NULL value.

    Root cause this solves:
    - PRs synced before the milestone_version column existed have NULL values.
    - GitHub PRs without an assigned milestone return ``milestone: null``,
      so the sync never fills the column automatically.

    This endpoint fills the gap by stamping the release's own ``version`` string
    onto every NULL row, making version-based filtering work immediately.
    """
    release = db.query(Release).filter(Release.release_id == release_id).first()
    if not release:
        from fastapi import HTTPException
        raise HTTPException(status_code=404, detail=f"Release {release_id} not found")

    if not release.version or release.version.upper() == "UNVERSIONED":
        return {
            "release_id": release_id,
            "release_name": release.release_name,
            "skipped": True,
            "reason": "Release has no version set (UNVERSIONED). Set a version first.",
            "updated": 0,
        }

    from models import PullRequest
    rows = (
        db.query(PullRequest)
        .filter(
            PullRequest.release_id == release_id,
            PullRequest.milestone_version.is_(None),
        )
        .all()
    )

    for pr in rows:
        pr.milestone_version = release.version

    db.commit()

    return {
        "release_id": release_id,
        "release_name": release.release_name,
        "version_applied": release.version,
        "updated": len(rows),
    }


