# Generated by GitHub Copilot
@router.get("/milestones/mapped", summary="Fetch GitHub milestones and map to release versions")
def fetch_milestones_mapped(
    repository: str | None = Query(default=None, description="owner/repo – defaults to OWNER/REPO env vars"),
    state: str = Query(default="all", description="open | closed | all"),
    db: Session = Depends(get_db),
) -> list[dict]:
    """Fetch milestones from GitHub and map each one to a release row by version.

    Matching is done by comparing the milestone title (case-insensitive, with
    optional leading 'v' stripped) against the ``version`` column of the
    releases table.

    Returns a list of milestone objects, each augmented with a
    ``matched_release`` key (release_id, release_name, status) when a
    matching release is found, or ``null`` when no match exists.
    """
    if repository:
        parts = repository.split("/", 1)
        owner, repo = (parts[0], parts[1]) if len(parts) == 2 else (GITHUB_OWNER or "", parts[0])
    else:
        owner, repo = GITHUB_OWNER or "", GITHUB_REPO or ""

    if not owner or not repo:
        return []

    milestones = get_milestones(owner=owner, repo=repo, token=GITHUB_TOKEN, state=state)

    releases = db.query(Release).all()

    # Build version lookup: normalised version string -> Release
    version_map: dict[str, Release] = {}
    for rel in releases:
        if rel.version and rel.version.upper() != "UNVERSIONED":
            version_map[rel.version.lstrip("vV").lower()] = rel

    result = []
    for ms in milestones:
        title: str = ms.get("title") or ""
        normalised_title = title.lstrip("vV").lower()
        matched = version_map.get(normalised_title)
        result.append({
            "milestone_number": ms.get("number"),
            "title": title,
            "state": ms.get("state"),
            "due_on": ms.get("due_on"),
            "open_issues": ms.get("open_issues", 0),
            "closed_issues": ms.get("closed_issues", 0),
            "html_url": ms.get("html_url"),
            "matched_release": {
                "release_id": matched.release_id,
                "release_name": matched.release_name,
                "version": matched.version,
                "status": matched.status,
            } if matched else None,
        })

    return result


# Generated by GitHub Copilot
@router.post(
    "/milestones/{milestone_number}/apply-to-release/{release_id}",
    summary="Link a GitHub milestone to a release and populate version",
)
def apply_milestone_to_release(
    milestone_number: int,
    release_id: int,
    repository: str | None = Query(default=None, description="owner/repo"),
    db: Session = Depends(get_db),
) -> dict:
    """Fetch one GitHub milestone and apply its title as the version on the target
    release.  Also stamps ``milestone_version`` on every pull request belonging to
    that release so the PR table stays consistent.

    This is the correct way to resolve a release_name mismatch: explicitly tell
    the system which milestone belongs to which release, and the version column
    is updated accordingly.
    """
    if repository:
        parts = repository.split("/", 1)
        owner, repo = (parts[0], parts[1]) if len(parts) == 2 else (GITHUB_OWNER or "", parts[0])
    else:
        owner, repo = GITHUB_OWNER or "", GITHUB_REPO or ""

    if not owner or not repo:
        from fastapi import HTTPException
        raise HTTPException(status_code=400, detail="Repository owner/repo is required")

    milestones = get_milestones(owner=owner, repo=repo, token=GITHUB_TOKEN, state="all")
    milestone = next((m for m in milestones if m.get("number") == milestone_number), None)
    if not milestone:
        from fastapi import HTTPException
        raise HTTPException(status_code=404, detail=f"Milestone {milestone_number} not found in {owner}/{repo}")

    release = db.query(Release).filter(Release.release_id == release_id).first()
    if not release:
        from fastapi import HTTPException
        raise HTTPException(status_code=404, detail=f"Release {release_id} not found")

    milestone_title: str = milestone.get("title") or ""

    # Update version on the release
    release.version = milestone_title

    # Stamp milestone_version on every pull request for this release
    from models import PullRequest
    updated_prs = (
        db.query(PullRequest)
        .filter(PullRequest.release_id == release_id)
        .all()
    )
    for pr in updated_prs:
        pr.milestone_version = milestone_title

    db.commit()

    return {
        "release_id": release_id,
        "release_name": release.release_name,
        "version_set_to": milestone_title,
        "pull_requests_updated": len(updated_prs),
    }
